--
-- Table structure for table `farmers`
--

DROP TABLE IF EXISTS `farmers`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!40101 SET character_set_client = utf8 */;
CREATE TABLE `farmers` (
  `id` bigint(20) unsigned NOT NULL AUTO_INCREMENT,
  `farmer_key` varchar(32) DEFAULT NULL,
  `rsbsa_number` varchar(60) DEFAULT NULL,
  `first_name` varchar(100) NOT NULL,
  `middle_name` varchar(100) DEFAULT NULL,
  `last_name` varchar(100) NOT NULL,
  `address` text NOT NULL,
  `birthdate` date DEFAULT NULL,
  `birthplace` varchar(160) DEFAULT NULL,
  `civil_status` varchar(40) DEFAULT NULL,
  `spouse_name` varchar(160) DEFAULT NULL,
  `dependents` int(10) unsigned DEFAULT 0,
  `contact_number` varchar(40) DEFAULT NULL,
  `email` varchar(160) DEFAULT NULL,
  `sex` enum('Female','Male') NOT NULL,
  `photo_path` varchar(255) DEFAULT NULL,
  `gender_orientation` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL CHECK (json_valid(`gender_orientation`)),
  `sector` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL CHECK (json_valid(`sector`)),
  `farmer_organization_id` bigint(20) unsigned DEFAULT NULL,
  `province_id` bigint(20) unsigned DEFAULT NULL,
  `warehouse_id` bigint(20) unsigned DEFAULT NULL,
  `created_at` timestamp NOT NULL DEFAULT current_timestamp(),
  `is_ip_group_member` tinyint(1) NOT NULL DEFAULT 0,
  `mao_certification` varchar(60) DEFAULT NULL,
  `no_available_control_number` tinyint(1) NOT NULL DEFAULT 0,
  `valid_id_path` varchar(255) DEFAULT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `rsbsa_number` (`rsbsa_number`),
  UNIQUE KEY `farmers_farmer_key_unique` (`farmer_key`),
  KEY `farmer_organization_id` (`farmer_organization_id`),
  KEY `warehouse_id` (`warehouse_id`),
  CONSTRAINT `farmers_ibfk_1` FOREIGN KEY (`farmer_organization_id`) REFERENCES `farmer_organizations` (`id`),
  CONSTRAINT `farmers_ibfk_2` FOREIGN KEY (`warehouse_id`) REFERENCES `warehouse_offices` (`id`)
) ENGINE=InnoDB AUTO_INCREMENT=4483 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

