--
-- Table structure for table `landholdings`
--

DROP TABLE IF EXISTS `landholdings`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!40101 SET character_set_client = utf8 */;
CREATE TABLE `landholdings` (
  `id` bigint(20) unsigned NOT NULL AUTO_INCREMENT,
  `farmer_id` bigint(20) unsigned NOT NULL,
  `classification` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL CHECK (json_valid(`classification`)),
  `irrigated` tinyint(1) DEFAULT NULL,
  `harvest_sharing_lessor` decimal(5,2) DEFAULT NULL,
  `harvest_sharing_lessee` decimal(5,2) DEFAULT NULL,
  `palay_location` varchar(180) DEFAULT NULL,
  `harvested_area_hectares` decimal(10,3) DEFAULT NULL,
  `average_yield_per_hectare` decimal(10,3) DEFAULT NULL,
  `summer_yield_per_hectare` decimal(10,3) DEFAULT NULL,
  `third_crop_yield_per_hectare` decimal(10,3) DEFAULT NULL,
  `is_lessor` tinyint(1) NOT NULL DEFAULT 0,
  `is_lessee` tinyint(1) NOT NULL DEFAULT 0,
  `is_farm_worker` tinyint(1) NOT NULL DEFAULT 0,
  `is_farm_administrator` tinyint(1) NOT NULL DEFAULT 0,
  PRIMARY KEY (`id`),
  KEY `landholdings_farmer_idx` (`farmer_id`),
  CONSTRAINT `landholdings_ibfk_1` FOREIGN KEY (`farmer_id`) REFERENCES `farmers` (`id`)
) ENGINE=InnoDB AUTO_INCREMENT=5789 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

